    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">(EN) // (GJ)</span>"},{"quoi":"الاختيار","math":"المطلوب : كتابة النّسب المتساوية. نختار نظرية طالس لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: (EN) // (GJ).</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"في المثلّث AJG لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(EN) // (JG)</span>  و  <span dir=\"ltr\" class=\"expr pt\">E ∈ (AJ)</span>  و  <span dir=\"ltr\" class=\"expr pt\">N ∈ (AG)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AE</span><span class=\"den\">AJ</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AN</span><span class=\"den\">AG</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">EN</span><span class=\"den\">JG</span></span>"},{"quoi":"النتيجة","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AE</span><span class=\"den\">AJ</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AN</span><span class=\"den\">AG</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">EN</span><span class=\"den\">JG</span></span>"}],
    indice: "الرّؤوس تُقرأ انطلاقا من A : ثلاث نسب متساوية",
