    correction: [{"quoi":"المعطيات","math":"<span dir=\"ltr\" class=\"expr pt\">AT = 25</span>  و  <span dir=\"ltr\" class=\"expr pt\">HT = 5</span>  و  <span dir=\"ltr\" class=\"expr pt\">HS = 25</span>  و  <span dir=\"ltr\" class=\"expr pt\">(MT) // (HS)</span>"},{"quoi":"الاختيار","math":"المطلوب : حساب <span dir=\"ltr\" class=\"expr pt\">MT.</span> نختار علاقة شال <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span> لأنّ معطياتها متوفّرة <span dir=\"ltr\" class=\"expr pt\">: AT = 25</span>  و  <span dir=\"ltr\" class=\"expr pt\">HT = 5.</span> و لماذا لا مبرهنة المنتصفين ؟ لأنّها تحتاج منتصفَي ضلعين، و لا نعرف إلا منتصفا واحدا على الأكثر."},{"quoi":"القاعدة","math":"إذا كانت النقطة <span dir=\"ltr\" class=\"expr pt\">B</span> بين <span dir=\"ltr\" class=\"expr pt\">A</span> و <span dir=\"ltr\" class=\"expr pt\">C</span> فإنّ <span dir=\"ltr\" class=\"expr pt\">AC = AB + BC</span>"},{"quoi":"نطبّق","math":"<span dir=\"ltr\" class=\"expr pt\">AT = 25</span>  و  <span dir=\"ltr\" class=\"expr pt\">HT = 5</span>  إذن  <span dir=\"ltr\" class=\"expr pt\">AH = 30</span>  ، لأنّ <span dir=\"ltr\" class=\"expr pt\">AH = 25 + 5</span>"},{"quoi":"في المثلّث ASH لنا","math":"<span dir=\"ltr\" class=\"expr pt\">(MT) // (SH)</span>  و  <span dir=\"ltr\" class=\"expr pt\">M ∈ (AS)</span>  و  <span dir=\"ltr\" class=\"expr pt\">T ∈ (AH)</span>"},{"quoi":"حسب نظرية طالس لنا","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">AM</span><span class=\"den\">AS</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">AT</span><span class=\"den\">AH</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MT</span><span class=\"den\">SH</span></span>"},{"quoi":"نعوّض","math":"<span class=\"frac\" dir=\"ltr\"><span class=\"num\">25</span><span class=\"den\">30</span></span><span dir=\"ltr\" class=\"expr\"> = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">MT</span><span class=\"den\">25</span></span>"},{"quoi":"إذن","math":"<span dir=\"ltr\" class=\"expr pt\">MT = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">125</span><span class=\"den\">6</span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr pt\">MT = </span><span class=\"frac\" dir=\"ltr\"><span class=\"num\">125</span><span class=\"den\">6</span></span>"}],
